function iconsPanel(){const icons=iconState(),contexts=[['frontend','Website browser tab'],['admin','WordPress admin browser tab'],['builder','Builder editor browser tab']],symbols=[['auto','Automatic builder symbol'],['text','Letters'],['circle','Circle outline'],['diamond','Diamond outline'],['spark','Spark outline'],['leaf','Leaf outline'],['shield','Shield outline'],['grid','Grid outline'],['bricks','Bricks outline'],['oxygen','Oxygen outline']];return `<div class="bas-panel bas-icons-settings" id="bas-section-icons"><h2>5. ${t('Browser tab icons (favicons)')}</h2><p class="description">${t('These small icons appear in browser tabs, helping you tell the public website, WordPress admin and builder editor apart.')}</p><label class="bas-login-switch"><input id="bas-icons-enabled" type="checkbox" ${icons.enabled?'checked':''}> ${t('Use different icons in browser tabs')}</label><label class="bas-icon-environment"><input id="bas-icon-environment" type="checkbox" ${icons.environment_marker?'checked':''}> ${t('Mark the installation environment on generated favicons')}</label><p class="description">${t('A small letter and color distinguish Local, Development, Staging and Live tabs. A retained WordPress Site Icon stays unchanged.')}</p><div class="bas-icons-top"><label>${t('Website browser tab')} <select id="bas-icons-frontend-mode"><option value="generated" ${icons.frontend_mode==='generated'?'selected':''}>${t('Generate a website favicon')}</option><option value="wordpress" ${icons.frontend_mode==='wordpress'?'selected':''}>${t('Keep the WordPress Site Icon as favicon')}</option></select></label><label>${t('Builder color preset')} <select id="bas-icons-builder-style">${[['auto','Automatically detected'],['bricks','Bricks'],['elementor','Elementor'],['oxygen','Oxygen']].map(([value,label])=>`<option value="${value}" ${icons.builder_style===value?'selected':''}>${t(label)}</option>`).join('')}</select></label></div><p class="description">${t('In a detected builder editor tab, the favicon uses the builder color preset. Ordinary website tabs keep their website icon.')}</p><div class="bas-icons-grid">${contexts.map(([context,title])=>`<div class="bas-icon-card"><div class="bas-icon-card-top"><span data-icon-preview="${context}">${context==='frontend'&&icons.frontend_mode==='wordpress'&&BAS_DATA.siteIcon?`<img src="${esc(BAS_DATA.siteIcon)}" width="56" height="56" alt="">`:iconPreviewSvg(context)}</span><strong>${t(title)}</strong></div><label>${t('Abbreviation (up to 3 characters)')} <input type="text" maxlength="3" data-icon-label="${context}" value="${esc(icons[context].label)}" placeholder="${esc(iconInitials(''))}"></label><label>${t('Symbol')} <select data-icon-symbol="${context}">${symbols.map(([value,label])=>`<option value="${value}" ${icons[context].symbol===value?'selected':''}>${t(label)}</option>`).join('')}</select></label><div class="bas-icon-colors">${[['background','Background color'],['foreground','Foreground color']].map(([key,label])=>`<label>${t(label)} <span><input type="checkbox" data-icon-auto="${context}:${key}" ${icons[context][key]?'':'checked'} aria-label="${t('Automatic from scheme')}"><input type="color" data-icon-color="${context}:${key}" value="${icons[context][key]||iconColors(context)[key==='background'?0:1]}" ${icons[context][key]?'':'disabled'}></span></label>`).join('')}</div></div>`).join('')}</div><p class="description">${t('Leave colors empty to follow the active scheme or builder preset.')}</p></div>`}
