function contrastPanel(){const s=window.basSchemes?.[selected];if(!s)return '';const login=loginPalette(),checks=[['Admin menu',s.menu,s.text],['Admin submenu',s.submenu,s.text],['Admin toolbar',s.bar,s.text],['Admin buttons',s.button,'#ffffff'],['Login background',login.page,textOn(login.page)],['Login button',login.button,textOn(login.button)]],items=checks.map(([name,bg,fg])=>{const ratio=contrast(bg,fg),good=ratio>=4.5,white=contrast(bg,'#ffffff'),dark=contrast(bg,'#17202b'),preferred=white>=dark?'#ffffff':'#17202b',suggest=contrast(bg,preferred)>=4.5?`${t('Try text')} ${preferred}`:`${t('Try background')} ${darken(bg)}`;return `<div class="bas-contrast-row"><span class="bas-contrast-sample" style="background:${bg};color:${fg}">Aa</span><span><strong>${t(name)}</strong><small>${bg} / ${fg}</small></span><span class="${good?'bas-contrast-good':'bas-contrast-low'}">${ratio.toFixed(1)}:1 · ${t(good?'Readable':'Check contrast')}</span>${good?'':`<small class="bas-contrast-suggestion">${suggest}</small>`}</div>`});return `<div class="bas-contrast-audit"><h3>${t('Color contrast check')}</h3><p class="description">${t('Estimated text contrast for this scheme and login palette. Other plugins can change the final appearance.')}</p><div class="bas-contrast-grid">${items.join('')}</div></div>`}
function refreshContrast(){const el=root.querySelector('#bas-contrast-audit');if(el)el.innerHTML=contrastPanel()}
function sectionNav(){const items=[['colors','Brand colors'],['atmosphere','Atmosphere'],['scheme','Scheme & toolbar'],['login','Login design'],['icons','Browser favicons'],['transfer','Import & export']];return `<nav class="bas-section-nav" aria-label="${t('Jump to a section')}"><span>${t('Jump to:')}</span>${items.map(([id,label])=>`<a href="#bas-section-${id}">${t(label)}</a>`).join('')}</nav>`}
