function updateDirty(){const dirty=isDirty(),bar=root.querySelector('.bas-sticky'),label=root.querySelector('#bas-unsaved-status');bar?.classList.toggle('is-dirty',dirty);if(label)label.textContent=dirty?t('Unsaved changes'):t('All changes saved')}
function reloadEditor(){if(isDirty()&&!window.confirm(t('Discard unsaved changes and reload the page?')))return;allowNavigation=true;location.reload()}
