function previewScheme(s){clearPreview();preview=document.createElement('style');preview.id='bas-preview';preview.textContent=`#adminmenu,#adminmenuback,#adminmenuwrap{background:${s.menu}}#adminmenu .wp-submenu,#wpadminbar .menupop .ab-sub-wrapper{background:${s.submenu}}#adminmenu a,#adminmenu .wp-submenu a,#adminmenu div.wp-menu-image:before,#wpadminbar .ab-item{color:${s.text}!important}#adminmenu li.current a.menu-top,#adminmenu li.wp-has-current-submenu a.wp-has-current-submenu,#adminmenu li.menu-top:hover{background:${s.highlight}}#wpadminbar{background:${s.bar}}.wp-core-ui .button-primary{background:${s.button};border-color:${s.button}}`;document.head.append(preview);window.BAS_ENV_UPDATE?.()}
function clearPreview(){preview?.remove();preview=null;window.BAS_ENV_UPDATE?.()}
function status(s){for(const id of ['bas-status','bas-top-status']){const el=document.getElementById(id);if(el)el.textContent=s}}
